import { useState } from 'react';
import { JxButton } from '@jinx-ui/react';

export type User = {
  id: string;
  name: string;
  role: string;
  active: boolean;
};

type UsersTableProps = {
  users: User[];
  pageSize?: number;
};

// Только JxButton подтверждён в README пакета; таблица и метка собраны
// на jx-* классах CSS-контракта @jinx-ui/core — сверь имена классов со сборкой.
export default function UsersTable({ users, pageSize = 10 }: UsersTableProps) {
  const [page, setPage] = useState(0);

  const pageCount = Math.max(1, Math.ceil(users.length / pageSize));
  const current = Math.min(page, pageCount - 1);
  const start = current * pageSize;
  const rows = users.slice(start, start + pageSize);

  return (
    <div className="jx-stack">
      <table className="jx-table">
        <thead>
          <tr>
            <th scope="col">Имя</th>
            <th scope="col">Роль</th>
            <th scope="col">Статус</th>
          </tr>
        </thead>
        <tbody>
          {rows.map((user) => (
            <tr key={user.id}>
              <td>{user.name}</td>
              <td>{user.role}</td>
              <td>
                <span
                  className={
                    user.active
                      ? 'jx-badge jx-badge--success'
                      : 'jx-badge jx-badge--neutral'
                  }
                >
                  {user.active ? 'Активен' : 'Отключён'}
                </span>
              </td>
            </tr>
          ))}
          {rows.length === 0 && (
            <tr>
              <td colSpan={3}>Пользователей нет</td>
            </tr>
          )}
        </tbody>
      </table>

      <nav
        className="jx-cluster"
        aria-label="Постраничная навигация"
        style={{ gap: 'var(--jx-space-2)' }}
      >
        <JxButton
          variant="ghost"
          disabled={current === 0}
          onClick={() => setPage(current - 1)}
        >
          Назад
        </JxButton>
        <span aria-live="polite">
          Страница {current + 1} из {pageCount}
        </span>
        <JxButton
          variant="ghost"
          disabled={current >= pageCount - 1}
          onClick={() => setPage(current + 1)}
        >
          Вперёд
        </JxButton>
      </nav>
    </div>
  );
}

